def minAxisLinkCost(points):
    n = len(points)
    if n == 1:
        return 0
    edges = []
    for axis in (0, 1):
        order = sorted(range(n), key=lambda i: points[i][axis])
        for a, b in zip(order, order[1:]):
            dx = abs(points[a][0] - points[b][0])
            dy = abs(points[a][1] - points[b][1])
            edges.append((min(dx, dy), a, b))
    edges.sort()
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    total = 0
    for c, a, b in edges:
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[ra] = rb
            total += c
    return total
